        details_error(self)

        self.state = {
            "state": {
                "color": {},
                "labels": {},
                "facets": {},
                "x": {},
                "x_formatting": {},
                "y": {},
                "y_formatting": {},
                "filter_control": {},
                "controls_container": {},
                "controls_style": {},
                "dropdown_style": {},
                "button_style": {},
                "legend_categorical": {},
                "legend_container": {},
                "popup": {},
                "axes_highlights": {},
                "annotations": {"defaults": {}},
                "chart_bg": {},
                "layout": {
                    "border": {"top": {}, "right": {}, "bottom": {}, "left": {}}
                },
            }
        }

        list_sort_by = ["none", "unstacked", "stacked"] + [None]
        if sort_by not in list_sort_by:
            raise ValueError(
                f"`sort_by` must be one of: ['none', 'unstacked', 'stacked']"
            )
        elif sort_by in list_sort_by and sort_by is not None:
            filtered_dict = {
                k: v
                for (k, v) in {
                    "none": "none",
                    "unstacked": "unstacked",
                    "stacked": "stacked",
                }.items()
                if sort_by in k
            }
            if len(filtered_dict) > 0:
                self.state["state"]["sort_by"] = filtered_dict[sort_by]

